function mapValues(obj, f) {
  // return a new object with each value transformed by f
}

exercises.solution:
function mapValues(obj, f) {
  const out = {}
  for (const [k, v] of Object.entries(obj)) {
    out[k] = f(v)
  }
  return out
}

